'use strict';
let hydraulic=null,hydraulicParishes=new Map(),hydraulicQ10Parishes=new Map();
const pilotOption=document.createElement('option');pilotOption.value='pilot-q10';pilotOption.textContent='Coimbra · Q10 diário, hipótese de 6 h';$('view').append(pilotOption);
const hydraulicValue=value;value=function(p){let v=$('view').value;if(v==='current'||v==='pilot-q10')return (v==='current'?hydraulicParishes:hydraulicQ10Parishes).get(p.dtmnfr)?.experimental_risk_class??null;return hydraulicValue(p);};
const hydraulicColor=color; color=function(v){return ['current','pilot-q10'].includes($('view').value)?(v==null?colors[0]:colors[v]):hydraulicColor(v);};
const hydraulicLabel=label;label=function(v){return ['current','pilot-q10'].includes($('view').value)?(v==null?'Sem mancha calculada':names[v]+' · experimental'):hydraulicLabel(v);};
const hydraulicRender=render;render=function(){hydraulicRender();if(!hydraulic)return;let v=$('view').value,active=v==='current'||v==='pilot-q10',q10=v==='pilot-q10';for(let id of ['pilot-flood','pilot-parishes','pilot-outline'])if(map?.getLayer(id))map.setLayoutProperty(id,'visibility',active?'visible':'none');if(!active)return;
 $('period').parentElement.hidden=true;document.querySelector('[data-layer=risk]').parentElement.hidden=true;map.setLayoutProperty('risk','visibility','none');map.getSource('pilot-flood').setData(hydraulic[q10?'q10':'footprint']);map.getSource('pilot-parishes').setData(hydraulic[q10?'q10parishes':'parishes']);map.setPaintProperty('parishes-fill','fill-opacity',.04);
 $('legend').innerHTML='<b>'+(q10?'Q10 diário · hipótese de 6 horas':'Estimativa atual · piloto Coimbra')+'</b><p>Azul: rio. Mancha amarela a vermelha: água calculada fora do canal assumido. Freguesias translúcidas: interseção com essa mancha.</p><small>Experimental, sem calibração. Fora do contorno pontilhado: sem cálculo hidráulico.</small>';
 document.querySelector('.map-note').textContent=q10?'Hipótese Q10 diário de 6 h · não é cheia em curso nem mancha T10 oficial':'Coimbra · estimativa hidráulica com caudal diário de modelo · '+date(hydraulic.info.valid_time);
 document.querySelectorAll('.result').forEach(row=>{let p=data.parishes.features.find(f=>f.properties.dtmnfr===row.dataset.code)?.properties;if(p){let b=row.querySelector('.badge'),n=value(p);if(b){b.textContent=label(n);b.style.background=color(n)+'30';}}});
};
const hydraulicShow=showParish;showParish=function(code,fly=true){hydraulicShow(code,fly);if(!hydraulic||!['current','pilot-q10'].includes($('view').value))return;let q10=$('view').value==='pilot-q10',p=(q10?hydraulicQ10Parishes:hydraulicParishes).get(code),root=$('detail-content');root.querySelectorAll('.badge').forEach(b=>b.textContent=p?'Mancha intersecta a freguesia · experimental':'Sem mancha calculada nesta freguesia');root.insertAdjacentHTML('afterbegin','<h3>Hidráulica experimental · Coimbra</h3><p>'+(p?'Interseção calculada com a mancha '+(q10?'hipotética Q10 diário durante 6 h':'estimada atual')+'.':'Sem interseção calculada. Fora do piloto, situação desconhecida; dentro, a ausência de mancha depende das hipóteses do modelo.')+'</p>'+(p?'<dl>'+metric('Área intersectada',num(p.flooded_area_m2/10000,2)+' ha')+metric('Residentes expostos estimados',num(p.exposed_residents_estimate,2))+metric('0–14 anos · estimativa',num(p.exposed_children_estimate,2))+metric('65+ anos · estimativa',num(p.exposed_elderly_estimate,2))+'</dl><p>Distribuição uniforme dos Censos BGRI2021 na área; valores fracionários são estimativas, não contagens de pessoas presentes.</p>':''));};
async function loadHydraulics(){let keys=['hydraulic-pilot.json','hydraulic-current.geojson','hydraulic-q10.geojson','hydraulic-parishes.geojson','hydraulic-q10-parishes.geojson','hydraulic-coverage.geojson'];let a=await Promise.all(keys.map(get));hydraulic={info:a[0],footprint:a[1],q10:a[2],parishes:a[3],q10parishes:a[4],coverage:a[5]};hydraulicParishes=new Map(a[3].features.map(f=>[f.properties.dtmnfr,f.properties]));hydraulicQ10Parishes=new Map(a[4].features.map(f=>[f.properties.dtmnfr,f.properties]));
 if(!map.getSource('pilot-flood')){for(let [id,d] of [['pilot-flood',a[1]],['pilot-parishes',a[3]],['pilot-outline',a[5]]])map.addSource(id,{type:'geojson',data:d});let ramp=['match',['get','hazard_class'],1,colors[1],2,colors[2],3,colors[3],4,colors[4],colors[5]];map.addLayer({id:'pilot-parishes',type:'fill',source:'pilot-parishes',paint:{'fill-color':['match',['get','experimental_risk_class'],1,colors[1],2,colors[2],3,colors[3],4,colors[4],colors[5]],'fill-opacity':.28}});map.addLayer({id:'pilot-flood',type:'fill',source:'pilot-flood',paint:{'fill-color':ramp,'fill-opacity':.8}});map.addLayer({id:'pilot-outline',type:'line',source:'pilot-outline',paint:{'line-color':'#173c65','line-dasharray':[3,3],'line-width':2}});map.on('click','pilot-parishes',e=>showParish(e.features[0].properties.dtmnfr,false));}
 let i=a[0],c=i.current;document.querySelector('.notice').innerHTML='<b>Piloto hidráulico · Mondego / Coimbra</b><p>Caudal estimado '+num(c.discharge_m3s,1)+' m³/s · nível de referência '+num(c.reference_water_level_m_egm2008,2)+' m EGM2008 · mancha fora do canal '+num(c.overbank_area_m2/10000,2)+' ha.</p><p>'+date(i.valid_time)+' · GloFAS diário, propagação horária. Canal assumido de 150 m, terreno de 30 m; sem descargas medidas nem calibração. A largura real do rio pode alterar a mancha.</p><button id="pilot-focus">Ver piloto Coimbra</button> <a href="report.html#hydraulic-pilot">Estudo e limites ↗</a>';$('pilot-focus').onclick=()=>{map.fitBounds([[-8.49,40.17],[-8.36,40.25]],{padding:55});};render();}
const hydraulicReload=reload;reload=async function(){await hydraulicReload();try{await loadHydraulics();}catch(e){document.querySelector('.map-note').textContent='Atualização hidráulica indisponível · consultar data original';}};
